import{_ as o,l,o as e,c as n,v as t,p,x as r,d as s,i as h,S as m}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"外部性与庇古税","description":"","frontmatter":{"title":"外部性与庇古税","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/externality-pigou.md","filePath":"econ/externality-pigou.md","lastUpdated":1789023840000}'),d={name:"econ/externality-pigou.md"};function c(E,a,u,f,q,B){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="外部性与庇古税" tabindex="-1">外部性与庇古税 <a class="header-anchor" href="#外部性与庇古税" aria-label="Permalink to &quot;外部性与庇古税&quot;">​</a></h1><div class="epigraph"><p>私人净产品与社会净产品发生歧义之处，正是产业需要国家干预的地方。</p><footer>—— 据 Pigou, The Economics of Welfare, 1920 整理</footer></div><p><a href="/econ/sunspot-equilibrium">上一课</a>（太阳黑子均衡）。在此之上，核收到竞争均衡：人多、可结盟、商品列全时，讨价还价的剩余被竞争掉。<a href="/econ/welfare-theorems">福利第一定理</a>也站在同一商品空间上。缺口是：有些影响根本没有对应的商品。工厂的烟进了邻居的效用，但烟没有价格、不能拿去核里阻塞。本课打开「市场失灵」课序，只钉外部性与一阶纠正，不预支科斯谈判。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>竞争均衡把每人的 MRS 对齐到同一组相对价格。若 \\(i\\) 的效用还直接依赖 \\(j\\) 的行动 \\(a^j\\)，一阶条件里多出一项 \\(\\partial u^i/\\partial a^j\\)，市场价格看不见它。私人边际成本（或收益）与社会边际成本分叉，均衡配置一般不再帕累托有效。核同样失效：联盟「带着自己的禀赋走开」时，污染是否跟着走，资源集没有定义。</p><p>缺口不是再证存在性，而是：在商品空间漏列一项时，如何用可观察的税把漏掉的边际搬回决策者的一阶条件。庇古的答案是单位税（或补贴）等于边际外部损害（或收益）。</p><h3 id="外部效应不是「互相影响」" tabindex="-1">外部效应不是「互相影响」 <a class="header-anchor" href="#外部效应不是「互相影响」" aria-label="Permalink to &quot;外部效应不是「互相影响」&quot;">​</a></h3><p>两人在盒里交易也互相影响，但那是通过价格与禀赋，已经内部化。外部性是非市场的直接进入：生产函数或效用函数的自变量里出现了别人的选择，而这个选择没有作为商品被定价。金钱外部性（pecuniary）只改价格，第一定理仍成立；技术外部性才拆有效性。</p><p><span class="marginnote">标准教具：边际损害 \\(\\mathrm{MD}(q)\\) 随排放升，私人边际成本 \\(\\mathrm{MC}(q)\\) 不含它。社会有效点满足 \\(\\mathrm{MC}(q^*)+\\mathrm{MD}(q^*)=\\mathrm{MB}(q^*)\\)。从量税 \\(t=\\mathrm{MD}(q^*)\\) 使私人一阶条件与社会重合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把商品空间扩一维：把排放 \\(e\\) 写成带负价格的商品。若能为 \\(e\\) 建市场，问题退回完整市场的第一定理。做不到时，计划者选定额税 \\(t\\)，厂商面对 \\(\\mathrm{MC}(q)+t\\)。最优 \\(t\\) 等于有效点上的边际外部损害，不是「损害的平均值」，也不是总损害除以产量。</p><p>补贴对称：正外部性把私人收益写低了，补贴补齐边际。配额加可交易许可在完全信息、无不确定性时与庇古税等价——都是把影子价格塞回私人问题。本课用税，因为后课归宿、次优都从价税、从量税说话。</p>',12)),(e(),p(m,null,{default:r(()=>[h(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MISS%5B%22%E5%95%86%E5%93%81%E7%A9%BA%E9%97%B4%E6%BC%8F%E5%88%97%20e%22%5D%20--%3E%20GAP%5B%22%E7%A7%81%E4%BA%BA%20MC%20%E2%89%A0%20%E7%A4%BE%E4%BC%9A%20MC%22%5D%0A%20%20GAP%20--%3E%20PIGOU%5B%22t%20%3D%20MD(q*)%22%5D%0A%20%20PIGOU%20--%3E%20FOC%5B%22%E7%A7%81%E4%BA%BA%E4%B8%80%E9%98%B6%E6%9D%A1%E4%BB%B6%E5%AF%B9%E9%BD%90%22%5D%0A%20%20FOC%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%B0%88%E4%B8%8D%E6%88%90%E7%A8%8E%E6%97%B6%E6%80%8E%E4%B9%88%E5%8A%9E%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>信息不免费。计划者要知道 \\(\\mathrm{MD}\\) 在 \\(q^*\\) 处的值，而 \\(q^*\\) 又取决于税。这是圆周。本课只写完全信息下的一阶纠正；谈判与产权是下一课对这个圆周的另一条出路。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>税改变的是相对价格，不是偏好。决策者仍最大化私人目标，只是预算或成本里多了一项 \\(t e\\)。对齐发生在边际：inframarginal 的总剩余转移给谁，有效性不管——那是后课归宿。配额钉数量、税钉价格，不确定下两者分开，Weitzman 的比较不在本课。</p><p>多源排放时，统一税率只在边际损害只取决于总量时正确。损害随地点变，就要分化税率，等于承认「排放」其实是许多不同商品。庇古工具的精度跟着商品定义走。</p><p>与<a href="/econ/welfare-theorems">第二定理</a>的差别：第二定理用总额转移改购买力，相对价格仍是有效价格。庇古税故意扭一项相对价格，因为那一项本来缺市场。它不是总额税，因此后课的归宿与次优都会找上门：楔子一旦留下，就不能假装其余切条件自动最优。</p><h3 id="税与配额在确定世界里等价" tabindex="-1">税与配额在确定世界里等价 <a class="header-anchor" href="#税与配额在确定世界里等价" aria-label="Permalink to &quot;税与配额在确定世界里等价&quot;">​</a></h3><p>完全信息、无不确定性时，钉住 \\(q^*\\) 的配额与 \\(t=\\mathrm{MD}(q^*)\\) 的税给出同一点；可交易许可把配额做成市场价格，价格应等于这笔税。Weitzman 的分开发生在成本曲线不确定时：收益陡、成本平，数量工具更稳；反过来价工具更稳。本课不选工具，只认「缺的那一列要用某个影子价格补回」。</p><p>正外部性对称：接种、基础研究，私人 MB 低于社会 MB，补贴补差。受益人分散时，补贴发给谁变成免费搭车，下一课把人数推到极端。金钱外部性（股价涨、工资变）已经在瓦尔拉斯会计里，再征一笔「涨价税」会叠扭曲。</p><p><span class="marginnote">测量 \\(\\mathrm{MD}(q^*)\\) 需要评价健康、生态或利润损失，并且 \\(q^*\\) 与 \\(t\\) 同时决定。迭代估税是实践，不是定理。本课的 \\(t\\) 是有效点上的那一个数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>第一定理的假设是完整市场，不是「无政府」。庇古税是用一种扭曲去补一种漏列；若经济里已经有其他扭曲，单补这一个可能更糟——<a href="/econ/theory-of-second-best">次优</a>会回收这句话。非凸（临界污染、不可分）让「边际税」没有良好定义的 \\(q^*\\)。</p><p>也不要把庇古税读成现实环保法的说明书。税率要边际损害，损害要评价健康与生态，那是测度，不是本课的存在性。科斯将问：若产权清晰、谈判免费，还要不要税。</p><p>生产外部性与消费外部性同一句话：漏列的是别人目标函数里的自变量。金钱外部性只改价格，不改技术，第一定理仍成立，不必征税。</p><p>后课默认：谈到「市场失灵」的第一种，指技术外部性；一阶纠正是把 \\(\\mathrm{MD}\\) 写成税。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>核与第一定理要求商品列全；漏列的直接影响是技术外部性。</li><li>庇古税把有效点上的边际损害写进私人一阶条件。</li><li>税对齐边际，不决定谁承担 inframarginal 负担。</li><li>计划者需要 \\(\\mathrm{MD}(q^*)\\)；下一课用谈判绕开这个信息。</li><li>出处：Pigou, <em>The Economics of Welfare</em>, 1920。</li></ul>',16))])}const D=o(d,[["render",c]]);export{A as __pageData,D as default};
